// OrderApi.Domain — no ASP.NET or EF references
namespace OrderApi.Domain.Orders;

public sealed class Order
{
    public Guid Id { get; private set; }
    public string CustomerId { get; private set; } = "";
    public OrderStatus Status { get; private set; }

    public static Order Create(string customerId)
    {
        if (string.IsNullOrWhiteSpace(customerId))
            throw new DomainException("CustomerId required");
        return new Order { Id = Guid.NewGuid(), CustomerId = customerId, Status = OrderStatus.Pending };
    }

    public void Ship()
    {
        if (Status != OrderStatus.Paid)
            throw new DomainException("Cannot ship unpaid order");
        Status = OrderStatus.Shipped;
    }
}

// OrderApi.Application
public sealed record PlaceOrderCommand(string CustomerId) : IRequest<OrderDto>;

public interface IOrderRepository
{
    Task AddAsync(Order order, CancellationToken ct);
    Task SaveChangesAsync(CancellationToken ct);
}

public sealed class PlaceOrderHandler(IOrderRepository repo) : IRequestHandler<PlaceOrderCommand, OrderDto>
{
    public async Task<OrderDto> Handle(PlaceOrderCommand cmd, CancellationToken ct)
    {
        var order = Order.Create(cmd.CustomerId);
        await repo.AddAsync(order, ct);
        await repo.SaveChangesAsync(ct);
        return new OrderDto(order.Id, order.CustomerId, order.Status.ToString());
    }
}

// OrderApi.Infrastructure
public sealed class EfOrderRepository(AppDbContext db) : IOrderRepository
{
    public Task AddAsync(Order order, CancellationToken ct)
    {
        db.Orders.Add(OrderMapper.ToPersistence(order));
        return Task.CompletedTask;
    }
    public Task SaveChangesAsync(CancellationToken ct) => db.SaveChangesAsync(ct);
}

// OrderApi.Api — Presentation
app.MapPost("/orders", async (PlaceOrderCommand cmd, ISender mediator, CancellationToken ct) =>
{
    var result = await mediator.Send(cmd, ct);
    return Results.Created($"/orders/{result.Id}", result);
});

// Program.cs DI wiring
builder.Services.AddMediatR(cfg => cfg.RegisterServicesFromAssembly(typeof(PlaceOrderCommand).Assembly));
builder.Services.AddScoped<IOrderRepository, EfOrderRepository>();

public class PlaceOrderHandlerTests
{
    [Fact]
    public async Task Handle_creates_order()
    {
        var repo = new FakeOrderRepository();
        var handler = new PlaceOrderHandler(repo);

        var result = await handler.Handle(new PlaceOrderCommand("cust-1"), CancellationToken.None);

        result.CustomerId.Should().Be("cust-1");
        repo.Orders.Should().HaveCount(1);
        repo.Orders[0].Status.Should().Be(OrderStatus.Pending);
    }
}

file sealed class FakeOrderRepository : IOrderRepository
{
    public List<Order> Orders { get; } = [];
    public Task AddAsync(Order order, CancellationToken ct) { Orders.Add(order); return Task.CompletedTask; }
    public Task SaveChangesAsync(CancellationToken ct) => Task.CompletedTask;
}
